const express = require('express');
const { Kafka } = require('kafkajs');

const app = express();
const PORT = 4000;

// Configure Kafka client for Redpanda
const kafka = new Kafka({
  clientId: 'ingestion-service',
  brokers: ['localhost:9092']
});

const producer = kafka.producer();

app.use(express.json());

// Initialize Kafka producer
let producerReady = false;

async function initProducer() {
  try {
    await producer.connect();
    producerReady = true;
    console.log('Connected to Redpanda');
  } catch (error) {
    console.error('Failed to connect to Redpanda:', error);
    process.exit(1);
  }
}

app.post('/ingest/events', async (req, res) => {
  if (!producerReady) {
    return res.status(503).json({ error: 'Producer not ready' });
  }

  try {
    // Send the event to Redpanda topic
    await producer.send({
      topic: 'product-events',
      messages: [{
        key: req.body.event_id,
        value: JSON.stringify(req.body)
      }]
    });

    res.status(200).json({
      status: 'success',
      event_id: req.body.event_id
    });
  } catch (error) {
    console.error('Error sending to Redpanda:', error);
    res.status(500).json({ error: 'Failed to process event' });
  }
});

app.get('/health', (req, res) => {
  res.json({ status: 'healthy', producer_ready: producerReady });
});

// Initialize and start server
initProducer().then(() => {
  app.listen(PORT, () => {
    console.log(`Ingestion service listening on port ${PORT}`);
  });
});

// Graceful shutdown
process.on('SIGINT', async () => {
  console.log('Shutting down gracefully...');
  await producer.disconnect();
  process.exit(0);
});

