const { Kafka } = require('kafkajs');
const { createClient } = require('@clickhouse/client');

// Configure Kafka client for Redpanda
const kafka = new Kafka({
  clientId: 'consumer-service',
  brokers: ['localhost:9092']
});

// Configure ClickHouse client
const clickhouse = createClient({
  host: 'http://localhost:8123',
  database: 'analytics'
});

const consumer = kafka.consumer({ groupId: 'analytics-group' });

async function processEvent(eventData) {
  try {
    // Parse the event timestamp to DateTime format for ClickHouse
    const event_ts = new Date(eventData.event_ts).toISOString().slice(0, 19).replace('T', ' ');

    // Insert into the product_events table
    await clickhouse.insert({
      table: 'product_events',
      values: [{
        event_id: eventData.event_id,
        event_ts: event_ts,
        user_id: eventData.user_id,
        product_id: eventData.product_id,
        event_type: eventData.event_type,
        properties: JSON.stringify(eventData.properties)
      }],
      format: 'JSONEachRow'
    });

    console.log(`Processed event ${eventData.event_id} of type ${eventData.event_type}`);

    // Update aggregation tables
    await updateAggregations();

  } catch (error) {
    console.error('Error processing event:', error);
  }
}

async function updateAggregations() {
  try {
    // Update top_products table
    await clickhouse.query({
      query: `
        INSERT INTO analytics.top_products
        SELECT
          product_id,
          countIf(event_type = 'view') as view_count,
          countIf(event_type = 'cart') as cart_count,
          countIf(event_type = 'purchase') as purchase_count,
          sumIf(JSONExtractFloat(properties, 'price'), event_type = 'purchase') as revenue
        FROM analytics.product_events
        GROUP BY product_id
      `,
      format: 'JSONEachRow'
    });

    // Clear and rebuild conversion_funnel
    await clickhouse.query({
      query: 'TRUNCATE TABLE analytics.conversion_funnel'
    });

    await clickhouse.query({
      query: `
        INSERT INTO analytics.conversion_funnel
        SELECT
          event_type as step,
          uniq(user_id) as unique_users,
          count() as total_events
        FROM analytics.product_events
        GROUP BY event_type
        ORDER BY
          CASE
            WHEN event_type = 'view' THEN 1
            WHEN event_type = 'cart' THEN 2
            WHEN event_type = 'purchase' THEN 3
            ELSE 4
          END
      `,
      format: 'JSONEachRow'
    });

    // Clear and rebuild hourly_activity
    await clickhouse.query({
      query: 'TRUNCATE TABLE analytics.hourly_activity'
    });

    await clickhouse.query({
      query: `
        INSERT INTO analytics.hourly_activity
        SELECT
          toStartOfHour(event_ts) as hour,
          event_type,
          count() as event_count
        FROM analytics.product_events
        GROUP BY hour, event_type
        ORDER BY hour, event_type
      `,
      format: 'JSONEachRow'
    });

    // Clear and rebuild top_products to avoid duplicates
    await clickhouse.query({
      query: 'TRUNCATE TABLE analytics.top_products'
    });

    await clickhouse.query({
      query: `
        INSERT INTO analytics.top_products
        SELECT
          product_id,
          countIf(event_type = 'view') as view_count,
          countIf(event_type = 'cart') as cart_count,
          countIf(event_type = 'purchase') as purchase_count,
          sumIf(JSONExtractFloat(properties, 'price'), event_type = 'purchase') as revenue
        FROM analytics.product_events
        GROUP BY product_id
      `,
      format: 'JSONEachRow'
    });

  } catch (error) {
    console.error('Error updating aggregations:', error);
  }
}

async function main() {
  try {
    await consumer.connect();
    console.log('Connected to Redpanda as consumer');

    await consumer.subscribe({ topic: 'product-events', fromBeginning: true });
    console.log('Subscribed to product-events topic');

    await consumer.run({
      eachMessage: async ({ topic, partition, message }) => {
        const eventData = JSON.parse(message.value.toString());
        await processEvent(eventData);
      },
    });

  } catch (error) {
    console.error('Error in consumer service:', error);
    process.exit(1);
  }
}

// Graceful shutdown
process.on('SIGINT', async () => {
  console.log('Shutting down consumer gracefully...');
  await consumer.disconnect();
  process.exit(0);
});

main();

