const express = require('express');
const { createClient } = require('@clickhouse/client');

const app = express();
const PORT = 3000;

// Configure ClickHouse client
const clickhouse = createClient({
  host: 'http://localhost:8123',
  database: 'analytics'
});

app.use(express.json());

// GET /api/top-products - JSON array from analytics.top_products (limit 10)
app.get('/api/top-products', async (req, res) => {
  try {
    const result = await clickhouse.query({
      query: `
        SELECT
          product_id,
          view_count,
          cart_count,
          purchase_count,
          revenue
        FROM analytics.top_products
        ORDER BY purchase_count DESC, revenue DESC
        LIMIT 10
      `,
      format: 'JSONEachRow'
    });

    const data = await result.json();
    res.json(data);
  } catch (error) {
    console.error('Error fetching top products:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// GET /api/funnel - JSON array from analytics.conversion_funnel
app.get('/api/funnel', async (req, res) => {
  try {
    const result = await clickhouse.query({
      query: `
        SELECT
          step,
          unique_users,
          total_events
        FROM analytics.conversion_funnel
        ORDER BY
          CASE
            WHEN step = 'view' THEN 1
            WHEN step = 'cart' THEN 2
            WHEN step = 'purchase' THEN 3
            ELSE 4
          END
      `,
      format: 'JSONEachRow'
    });

    const data = await result.json();
    res.json(data);
  } catch (error) {
    console.error('Error fetching funnel data:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// GET /api/hourly - JSON array from analytics.hourly_activity
app.get('/api/hourly', async (req, res) => {
  try {
    const result = await clickhouse.query({
      query: `
        SELECT
          formatDateTime(hour, '%Y-%m-%d %H:00:00') as hour,
          event_type,
          event_count
        FROM analytics.hourly_activity
        ORDER BY hour, event_type
      `,
      format: 'JSONEachRow'
    });

    const data = await result.json();
    res.json(data);
  } catch (error) {
    console.error('Error fetching hourly activity:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.get('/health', (req, res) => {
  res.json({ status: 'healthy' });
});

app.listen(PORT, () => {
  console.log(`Egress API listening on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('Shutting down gracefully...');
  process.exit(0);
});

